insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('1d0fd5fd-ee00-4763-8284-902527ddb97e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Foundations of Social Stratification: Inequality, Hierarchy, and Life Chances', 'This opening unit establishes the central vocabulary of the course. Students learn that stratification is not simply unequal outcomes; it is the patterned organization of advantage, disadvantage, honor, power, and life chances.', 0),
  ('37887119-0d64-4b2b-bafd-b2c05d2d96a5', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1d0fd5fd-ee00-4763-8284-902527ddb97e', 'subtopic'::public.curated_course_node_type, 'Core Concepts', 'Students learn the difference between inequality as a distribution and stratification as a durable social hierarchy.', 0),
  ('476603f3-65e0-4657-bb46-f036158e1530', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '37887119-0d64-4b2b-bafd-b2c05d2d96a5', 'concept'::public.curated_course_node_type, 'Strata, hierarchy, and ranking', null, 0),
  ('09796d60-00f1-4b17-85cd-4c1ca10662c7', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '37887119-0d64-4b2b-bafd-b2c05d2d96a5', 'concept'::public.curated_course_node_type, 'Life chances and opportunity', null, 1),
  ('49e62503-bdf1-4c8c-b18d-35472e305b89', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '37887119-0d64-4b2b-bafd-b2c05d2d96a5', 'concept'::public.curated_course_node_type, 'Privilege, domination, and disadvantage', null, 2),
  ('0773f29a-bbfd-45c8-a11e-f78bb092b6c7', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '37887119-0d64-4b2b-bafd-b2c05d2d96a5', 'concept'::public.curated_course_node_type, 'Open and closed stratification systems', null, 3),
  ('84fdaec6-ce48-490e-87ec-46db2f2308df', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1d0fd5fd-ee00-4763-8284-902527ddb97e', 'subtopic'::public.curated_course_node_type, 'Dimensions of Inequality', 'The point is to see that inequality has economic, cultural, political, spatial, and institutional dimensions.', 1),
  ('9d25958a-bb2f-4da8-a77f-c6680ea602dd', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '84fdaec6-ce48-490e-87ec-46db2f2308df', 'concept'::public.curated_course_node_type, 'Income, wealth, status, and power', null, 0),
  ('886f33bf-1366-434e-a4d6-56880db3092d', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '84fdaec6-ce48-490e-87ec-46db2f2308df', 'concept'::public.curated_course_node_type, 'Education, health, housing, and work', null, 1),
  ('f3e6926e-0d24-4ce1-8dc3-09d983ed499f', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '84fdaec6-ce48-490e-87ec-46db2f2308df', 'concept'::public.curated_course_node_type, 'Rights, recognition, and citizenship', null, 2),
  ('99b28da6-24f0-4d6d-b44b-855560b63a12', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '84fdaec6-ce48-490e-87ec-46db2f2308df', 'concept'::public.curated_course_node_type, 'Local, national, and global inequality', null, 3),
  ('99afe45d-ef3b-4563-a217-adcca21dc528', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1d0fd5fd-ee00-4763-8284-902527ddb97e', 'subtopic'::public.curated_course_node_type, 'Why Stratification Persists', 'Students begin to ask why unequal systems reproduce themselves even when societies claim to value fairness.', 2),
  ('8e21fd6a-92d7-4b96-8e21-f73fe90eee00', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '99afe45d-ef3b-4563-a217-adcca21dc528', 'concept'::public.curated_course_node_type, 'Social reproduction', null, 0),
  ('85a29c46-117d-466a-b30c-77f6b0a94a14', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '99afe45d-ef3b-4563-a217-adcca21dc528', 'concept'::public.curated_course_node_type, 'Institutional inertia', null, 1),
  ('d5707ddb-bd56-4d1b-9ca3-b1d3f0b9aff2', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '99afe45d-ef3b-4563-a217-adcca21dc528', 'concept'::public.curated_course_node_type, 'Ideology and legitimacy', null, 2),
  ('1f2e40e6-a3c6-448c-9ba4-358d2b802439', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '99afe45d-ef3b-4563-a217-adcca21dc528', 'concept'::public.curated_course_node_type, 'Cumulative advantage and disadvantage', null, 3),
  ('05b55722-d85b-42f3-ae7f-f2876aaed4f5', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Theories of Stratification: Marx, Weber, Functionalism, Conflict, and Bourdieu', 'This unit gives students the major theoretical lenses used to explain social stratification. They learn to compare theories by what each sees, misses, and assumes about power and social order.', 1),
  ('77af1b25-c164-4abb-98b4-75373069ef36', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '05b55722-d85b-42f3-ae7f-f2876aaed4f5', 'subtopic'::public.curated_course_node_type, 'Classical Theories', 'Students connect the course to foundational sociological theory.', 0),
  ('53e8d38a-e69d-4fff-9719-b7912e1aea88', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '77af1b25-c164-4abb-98b4-75373069ef36', 'concept'::public.curated_course_node_type, 'Marx on class, exploitation, and capitalism', null, 0),
  ('b15694b3-ac7c-471c-96a7-cd35e5171560', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '77af1b25-c164-4abb-98b4-75373069ef36', 'concept'::public.curated_course_node_type, 'Weber on class, status, party, and life chances', null, 1),
  ('d2ecc4ed-a050-4888-ab93-dbb4f95a1665', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '77af1b25-c164-4abb-98b4-75373069ef36', 'concept'::public.curated_course_node_type, 'Durkheim on social order and division of labor', null, 2),
  ('bd03b4cf-8c90-4b92-8d8c-464846b8bce6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '77af1b25-c164-4abb-98b4-75373069ef36', 'concept'::public.curated_course_node_type, 'Functionalist explanations and their critics', null, 3),
  ('72e39e32-8adf-4522-a21b-0635175156c0', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '05b55722-d85b-42f3-ae7f-f2876aaed4f5', 'subtopic'::public.curated_course_node_type, 'Conflict and Reproduction Theories', 'The gist is understanding inequality as produced through domination, institutions, and struggle.', 1),
  ('649c9a4b-485d-44c0-a56c-409d6cdd2981', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '72e39e32-8adf-4522-a21b-0635175156c0', 'concept'::public.curated_course_node_type, 'Power resources and conflict', null, 0),
  ('624a8416-4343-4209-a729-6083b3ef8ff8', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '72e39e32-8adf-4522-a21b-0635175156c0', 'concept'::public.curated_course_node_type, 'Social closure and exclusion', null, 1),
  ('d1dea27c-03ad-4b63-b625-45ed98b18371', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '72e39e32-8adf-4522-a21b-0635175156c0', 'concept'::public.curated_course_node_type, 'Bourdieu: habitus, capital, and field', null, 2),
  ('24609938-e860-43b4-a478-e2cfe385395a', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '72e39e32-8adf-4522-a21b-0635175156c0', 'concept'::public.curated_course_node_type, 'Ideology, meritocracy, and legitimacy', null, 3),
  ('8516254d-bb46-4203-a5f6-5c11b2f20be6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '05b55722-d85b-42f3-ae7f-f2876aaed4f5', 'subtopic'::public.curated_course_node_type, 'Contemporary Extensions', 'Students learn how theories adapt to race, gender, global capitalism, and new forms of work.', 2),
  ('bf31dfa1-3790-4a6f-8377-8b8b43e0d24e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '8516254d-bb46-4203-a5f6-5c11b2f20be6', 'concept'::public.curated_course_node_type, 'Intersectionality', null, 0),
  ('f3bbbf57-f99a-4f70-b706-4095f7d6a7e3', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '8516254d-bb46-4203-a5f6-5c11b2f20be6', 'concept'::public.curated_course_node_type, 'Racial capitalism', null, 1),
  ('de80902b-3b62-40e7-8f10-1f8382093921', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '8516254d-bb46-4203-a5f6-5c11b2f20be6', 'concept'::public.curated_course_node_type, 'Feminist stratification theory', null, 2),
  ('53accb76-3935-4ab7-83d0-3a770dd4c289', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '8516254d-bb46-4203-a5f6-5c11b2f20be6', 'concept'::public.curated_course_node_type, 'Precarity, platform work, and neoliberalism', null, 3),
  ('703a0ad2-1c3b-44d1-b831-3939816c6394', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Class Structure, Class Consciousness, Work, and Labor Markets', 'Class remains a central organizer of life chances. Students learn how work, occupations, ownership, class identity, and labor-market institutions structure advantage.', 2),
  ('52459171-458f-4055-8081-75b669ccd5b5', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '703a0ad2-1c3b-44d1-b831-3939816c6394', 'subtopic'::public.curated_course_node_type, 'Class Location and Class Structure', 'Students learn how sociologists classify class positions and why classifications matter.', 0),
  ('c9a5a337-b46d-463c-925a-be1e36adec54', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '52459171-458f-4055-8081-75b669ccd5b5', 'concept'::public.curated_course_node_type, 'Ownership and employment relations', null, 0),
  ('9efcd95f-1c4b-43d2-b4a6-ed01e72ebf9f', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '52459171-458f-4055-8081-75b669ccd5b5', 'concept'::public.curated_course_node_type, 'Occupational class schemas', null, 1),
  ('94863e2b-a9c9-44c6-92fd-7669ce908006', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '52459171-458f-4055-8081-75b669ccd5b5', 'concept'::public.curated_course_node_type, 'Service, working, professional, and elite classes', null, 2),
  ('1a53cf13-df57-4475-bf80-6ec432b51396', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '52459171-458f-4055-8081-75b669ccd5b5', 'concept'::public.curated_course_node_type, 'Contradictory class locations', null, 3),
  ('1cd2d52d-4415-415f-a6c5-93ec3b425fbf', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '703a0ad2-1c3b-44d1-b831-3939816c6394', 'subtopic'::public.curated_course_node_type, 'Work and Labor Markets', 'The point is to connect stratification to wages, job quality, bargaining power, and institutional protection.', 1),
  ('c80c3818-4b39-48f0-b598-934eb566bc77', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1cd2d52d-4415-415f-a6c5-93ec3b425fbf', 'concept'::public.curated_course_node_type, 'Primary and secondary labor markets', null, 0);
