  ('00dff824-960a-4625-9ea5-85541a4cdfc6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0e39c887-5643-473a-a7d3-f1037c4587b3', 'concept'::public.curated_course_node_type, 'Class identity and class avoidance', null, 0),
