  ('bb536694-e37d-4952-9dc3-90b6019d2c91', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0e39c887-5643-473a-a7d3-f1037c4587b3', 'concept'::public.curated_course_node_type, 'Middle-class norms and respectability', null, 2),
  ('e39968f3-36fc-4c7f-bc23-2086c2721924', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0e39c887-5643-473a-a7d3-f1037c4587b3', 'concept'::public.curated_course_node_type, 'Collective action and class politics', null, 3),
  ('162848dc-254a-4b8c-aa02-f61e43010eff', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Income, Wealth, Assets, Debt, and Capital Accumulation', 'Income and wealth are related but not the same. Students learn how wages, assets, inheritance, debt, and policy create both short-term hardship and long-term advantage.', 3),
  ('204bfe50-9df1-47a6-9a7d-313387fcb106', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '162848dc-254a-4b8c-aa02-f61e43010eff', 'subtopic'::public.curated_course_node_type, 'Income Inequality', 'Students learn to measure flows of money and interpret changing income distributions.', 0),
  ('87ee9a11-da2c-4368-b0d7-afcbd9fc1b76', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '204bfe50-9df1-47a6-9a7d-313387fcb106', 'concept'::public.curated_course_node_type, 'Wages, salaries, transfers, and capital income', null, 0),
  ('144e3bc3-8c54-49fc-a216-8e65ef51840e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '204bfe50-9df1-47a6-9a7d-313387fcb106', 'concept'::public.curated_course_node_type, 'Median, mean, percentiles, and shares', null, 1),
  ('88b97c32-4446-4167-b4da-c035b43f73f6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '204bfe50-9df1-47a6-9a7d-313387fcb106', 'concept'::public.curated_course_node_type, 'Gini coefficient and top-income shares', null, 2),
  ('257263e0-d895-456a-9917-f60f995ccce4', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '204bfe50-9df1-47a6-9a7d-313387fcb106', 'concept'::public.curated_course_node_type, 'Household income and equivalence scales', null, 3),
  ('f1e370bc-2801-41bf-99b2-cb14a287afed', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '162848dc-254a-4b8c-aa02-f61e43010eff', 'subtopic'::public.curated_course_node_type, 'Wealth and Assets', 'The gist is understanding why wealth inequality is usually deeper and more durable than income inequality.', 1),
  ('b53262fd-db2c-47e4-9753-e56636238c41', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f1e370bc-2801-41bf-99b2-cb14a287afed', 'concept'::public.curated_course_node_type, 'Assets, home equity, retirement accounts, and business ownership', null, 0),
  ('f371612a-0efd-451a-a52c-ea326b11efb9', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f1e370bc-2801-41bf-99b2-cb14a287afed', 'concept'::public.curated_course_node_type, 'Inheritance and intergenerational transfers', null, 1),
  ('69e01a6d-201c-478a-840d-25164054ee51', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f1e370bc-2801-41bf-99b2-cb14a287afed', 'concept'::public.curated_course_node_type, 'Racial wealth gaps', null, 2),
  ('bc435449-c5d2-4e99-a2d3-5349cc44499e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f1e370bc-2801-41bf-99b2-cb14a287afed', 'concept'::public.curated_course_node_type, 'Financialization and capital accumulation', null, 3),
  ('4b0ab4e3-2a6b-43e7-8783-706cf1f9e447', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '162848dc-254a-4b8c-aa02-f61e43010eff', 'subtopic'::public.curated_course_node_type, 'Debt, Taxation, and Policy', 'Students learn how public rules shape private resources.', 2),
  ('43ff1afa-e7af-41c4-847f-4c4ad9198320', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '4b0ab4e3-2a6b-43e7-8783-706cf1f9e447', 'concept'::public.curated_course_node_type, 'Student, medical, consumer, and housing debt', null, 0),
  ('16d3e762-e9f8-4754-b5ad-58082767c2d6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '4b0ab4e3-2a6b-43e7-8783-706cf1f9e447', 'concept'::public.curated_course_node_type, 'Progressive and regressive taxation', null, 1),
  ('4e241c1a-d5b0-4abb-abf2-71bdde0d422d', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '4b0ab4e3-2a6b-43e7-8783-706cf1f9e447', 'concept'::public.curated_course_node_type, 'Capital gains and estate taxation', null, 2),
  ('51074c00-61ae-4f1e-b244-0d6bbd0a2477', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '4b0ab4e3-2a6b-43e7-8783-706cf1f9e447', 'concept'::public.curated_course_node_type, 'Tax credits, transfers, and public benefits', null, 3),
  ('f501d6d2-1b8c-4041-9521-4c1edc9dee06', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Poverty, Material Hardship, Precarity, and Social Exclusion', 'Poverty is more than low income. This unit examines poverty as material deprivation, social exclusion, policy category, moral judgment, and lived experience.', 4),
  ('632baf6a-398f-452c-9c99-d9a19e0067d7', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f501d6d2-1b8c-4041-9521-4c1edc9dee06', 'subtopic'::public.curated_course_node_type, 'Measuring Poverty', 'Students learn how poverty definitions shape what societies see and what policies they justify.', 0),
  ('08825f57-606c-4228-ad7c-009f2e2b8d48', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '632baf6a-398f-452c-9c99-d9a19e0067d7', 'concept'::public.curated_course_node_type, 'Official poverty measure', null, 0),
  ('db9cf17e-91f0-4496-847c-503e1d22d662', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '632baf6a-398f-452c-9c99-d9a19e0067d7', 'concept'::public.curated_course_node_type, 'Supplemental poverty measure', null, 1),
  ('bc84293f-f1cf-4a9f-b0f9-a94f0c55db69', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '632baf6a-398f-452c-9c99-d9a19e0067d7', 'concept'::public.curated_course_node_type, 'Absolute and relative poverty', null, 2),
  ('628f38c7-e01f-472f-911c-103bbb651037', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '632baf6a-398f-452c-9c99-d9a19e0067d7', 'concept'::public.curated_course_node_type, 'Material hardship and deprivation indexes', null, 3),
  ('64122bc6-70eb-4e8e-867b-1daeb4f2ed73', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f501d6d2-1b8c-4041-9521-4c1edc9dee06', 'subtopic'::public.curated_course_node_type, 'Lived Experience and Stigma', 'The point is to understand how poverty affects daily life, identity, time, stress, and social belonging.', 1),
  ('366cf482-6b76-4bda-8f09-ff826bdf7a80', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '64122bc6-70eb-4e8e-867b-1daeb4f2ed73', 'concept'::public.curated_course_node_type, 'Food, housing, utility, and medical insecurity', null, 0),
  ('cdabf273-c3d6-4e00-bae3-3a630f93ecdc', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '64122bc6-70eb-4e8e-867b-1daeb4f2ed73', 'concept'::public.curated_course_node_type, 'Time poverty and bureaucratic burden', null, 1),
  ('298fcabf-4cf6-4435-85c1-268b63f7a550', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '64122bc6-70eb-4e8e-867b-1daeb4f2ed73', 'concept'::public.curated_course_node_type, 'Stigma and deservingness narratives', null, 2),
  ('681f8a91-6d54-479a-b29b-79e23054a499', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '64122bc6-70eb-4e8e-867b-1daeb4f2ed73', 'concept'::public.curated_course_node_type, 'Survival strategies and mutual aid', null, 3),
  ('e16b2824-98e0-4819-8aed-678367ab4ca2', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f501d6d2-1b8c-4041-9521-4c1edc9dee06', 'subtopic'::public.curated_course_node_type, 'Poverty Policy and Welfare States', 'Students compare policy responses and their political assumptions.', 2),
  ('30bd8e5d-4550-4d8a-bf3e-a7377671865a', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e16b2824-98e0-4819-8aed-678367ab4ca2', 'concept'::public.curated_course_node_type, 'Cash assistance and tax credits', null, 0),
  ('49845aad-5c35-4790-8c1f-a134bbb88fb8', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e16b2824-98e0-4819-8aed-678367ab4ca2', 'concept'::public.curated_course_node_type, 'SNAP, Medicaid, housing, and childcare', null, 1),
  ('6b79121f-663e-44b6-bb63-4d3c0972dff5', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e16b2824-98e0-4819-8aed-678367ab4ca2', 'concept'::public.curated_course_node_type, 'Work requirements and conditionality', null, 2),
  ('647d41d3-4883-41c3-a1ed-99864b24f280', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e16b2824-98e0-4819-8aed-678367ab4ca2', 'concept'::public.curated_course_node_type, 'Comparative welfare regimes', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e466d99a-ec4b-4459-a9c9-7e73ce782641', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Social Mobility, Opportunity, Inheritance, and the Life Course', 'Mobility asks whether inequality is inherited or escapable. Students learn how families, neighborhoods, schools, labor markets, and policy shape movement across generations.', 5),
  ('a92c30a1-5115-4f38-9909-99b0cb9a7ada', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e466d99a-ec4b-4459-a9c9-7e73ce782641', 'subtopic'::public.curated_course_node_type, 'Mobility Concepts', 'Students learn key distinctions that prevent vague claims about the American Dream or meritocracy.', 0),
  ('ff2bc9a9-f8f5-4930-9ac3-47960aa2747f', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a92c30a1-5115-4f38-9909-99b0cb9a7ada', 'concept'::public.curated_course_node_type, 'Intergenerational and intragenerational mobility', null, 0),
  ('e5c06f02-3c31-4779-920a-f57d9e7b7d90', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a92c30a1-5115-4f38-9909-99b0cb9a7ada', 'concept'::public.curated_course_node_type, 'Absolute and relative mobility', null, 1),
  ('f70266f2-02ed-4e19-a999-6e6a93e568c6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a92c30a1-5115-4f38-9909-99b0cb9a7ada', 'concept'::public.curated_course_node_type, 'Exchange and structural mobility', null, 2),
  ('7e05299d-52f1-4104-a552-9ba58874efbe', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a92c30a1-5115-4f38-9909-99b0cb9a7ada', 'concept'::public.curated_course_node_type, 'Mobility tables and transition matrices', null, 3),
  ('0d703efc-bcee-47a1-862f-a7e26b7c3fdb', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e466d99a-ec4b-4459-a9c9-7e73ce782641', 'subtopic'::public.curated_course_node_type, 'Opportunity and Inheritance', 'The gist is understanding how family resources transmit advantage.', 1),
  ('c388635a-3be3-4888-aabc-aade2acebcb4', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0d703efc-bcee-47a1-862f-a7e26b7c3fdb', 'concept'::public.curated_course_node_type, 'Wealth transfers and inheritance', null, 0),
  ('70a0e467-2e34-4345-ba11-99ba1adc0f3f', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0d703efc-bcee-47a1-862f-a7e26b7c3fdb', 'concept'::public.curated_course_node_type, 'Social capital and networks', null, 1),
  ('a7cd81ba-325c-4024-8ae2-89e185dae9fa', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0d703efc-bcee-47a1-862f-a7e26b7c3fdb', 'concept'::public.curated_course_node_type, 'Cultural capital and expectations', null, 2),
  ('f70c6d7a-2805-4ae1-85f5-0ed9b8b70dd4', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '0d703efc-bcee-47a1-862f-a7e26b7c3fdb', 'concept'::public.curated_course_node_type, 'Elite reproduction', null, 3),
  ('f3cff3ac-0069-4ce7-81bc-5cef65eb9c7e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e466d99a-ec4b-4459-a9c9-7e73ce782641', 'subtopic'::public.curated_course_node_type, 'Life Course and Turning Points', 'Students learn how advantage accumulates across childhood, education, work, family, and aging.', 2),
  ('cfa56fde-654c-41ed-9431-e5888e104731', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f3cff3ac-0069-4ce7-81bc-5cef65eb9c7e', 'concept'::public.curated_course_node_type, 'Sensitive periods and cumulative exposure', null, 0),
  ('9a843f45-5e7c-41fd-bcee-f77e2c8cb1d6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f3cff3ac-0069-4ce7-81bc-5cef65eb9c7e', 'concept'::public.curated_course_node_type, 'School transitions', null, 1),
  ('cd138c2b-4413-413b-893e-4d4cb67549b3', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f3cff3ac-0069-4ce7-81bc-5cef65eb9c7e', 'concept'::public.curated_course_node_type, 'Job loss, illness, and family disruption', null, 2),
  ('0526ca9b-15fa-4f2c-a3d3-b905a82c01fb', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'f3cff3ac-0069-4ce7-81bc-5cef65eb9c7e', 'concept'::public.curated_course_node_type, 'Retirement, aging, and late-life inequality', null, 3),
  ('1e0a8478-c4b3-47ea-97f1-c4fca13c5aca', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Education, Credentialing, Cultural Capital, and Inequality Reproduction', 'Education is often presented as the solution to inequality, but it can also reproduce it. Students learn how schools sort, certify, socialize, and stratify.', 6),
  ('a8fe27f6-36e3-4210-be68-e8bdcca6678f', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1e0a8478-c4b3-47ea-97f1-c4fca13c5aca', 'subtopic'::public.curated_course_node_type, 'Schooling and Opportunity', 'Students examine the promise and limits of education as a mobility engine.', 0),
  ('675d4152-a7fd-4ce7-a944-55ec09b1ad43', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a8fe27f6-36e3-4210-be68-e8bdcca6678f', 'concept'::public.curated_course_node_type, 'Educational attainment', null, 0),
  ('cf9b6b8f-c31e-4975-8577-afb0f9018dea', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a8fe27f6-36e3-4210-be68-e8bdcca6678f', 'concept'::public.curated_course_node_type, 'School funding and resource inequality', null, 1),
  ('f44eb36f-4a85-47c4-a2ba-a3af20ea2bab', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a8fe27f6-36e3-4210-be68-e8bdcca6678f', 'concept'::public.curated_course_node_type, 'Tracking and ability grouping', null, 2),
  ('d79cf41d-f90b-4683-8d87-55c7b092ff6a', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'a8fe27f6-36e3-4210-be68-e8bdcca6678f', 'concept'::public.curated_course_node_type, 'College access and completion', null, 3),
  ('e8040bec-2429-4d77-a2d6-4f723c1fc8e1', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1e0a8478-c4b3-47ea-97f1-c4fca13c5aca', 'subtopic'::public.curated_course_node_type, 'Credentials and Labor Markets', 'The point is to understand how diplomas become signals, gates, and class boundaries.', 1),
  ('26de763d-396d-40e2-810f-0c5f0de89381', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e8040bec-2429-4d77-a2d6-4f723c1fc8e1', 'concept'::public.curated_course_node_type, 'Credential inflation', null, 0),
  ('7f5f3f1b-04a4-4231-8490-ce50f29ef90e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e8040bec-2429-4d77-a2d6-4f723c1fc8e1', 'concept'::public.curated_course_node_type, 'Selective institutions and prestige', null, 1),
  ('507915c4-110e-423b-ab4c-d459ee0b53f8', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e8040bec-2429-4d77-a2d6-4f723c1fc8e1', 'concept'::public.curated_course_node_type, 'Student debt', null, 2),
  ('2d91e6e7-de29-48b2-a7ca-006a2d7d69fa', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e8040bec-2429-4d77-a2d6-4f723c1fc8e1', 'concept'::public.curated_course_node_type, 'Returns to education by race, gender, and class', null, 3),
  ('d26a5273-4778-43c6-b307-7b5a3acbea2c', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '1e0a8478-c4b3-47ea-97f1-c4fca13c5aca', 'subtopic'::public.curated_course_node_type, 'Cultural Capital and Hidden Curriculum', 'Students learn how family background shapes school success beyond formal ability.', 2),
  ('c6c23688-d259-4674-b453-f8be5e61bcb6', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'd26a5273-4778-43c6-b307-7b5a3acbea2c', 'concept'::public.curated_course_node_type, 'Concerted cultivation and natural growth', null, 0),
  ('81fcddda-ffe9-45d1-b2a3-2e939f7d285b', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'd26a5273-4778-43c6-b307-7b5a3acbea2c', 'concept'::public.curated_course_node_type, 'Teacher expectations', null, 1),
  ('ae8dfba3-0724-4956-8cd4-f810417abc73', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'd26a5273-4778-43c6-b307-7b5a3acbea2c', 'concept'::public.curated_course_node_type, 'Norms of professionalism and language', null, 2),
  ('fedc9534-9603-4471-b24e-ab55267e47ba', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'd26a5273-4778-43c6-b307-7b5a3acbea2c', 'concept'::public.curated_course_node_type, 'Belonging, stereotype threat, and institutional habitus', null, 3),
  ('17a812ef-5852-4617-ad1f-1ecc5a334bd7', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Status, Prestige, Culture, Taste, and Symbolic Boundaries', 'Stratification is not only material. Students learn how status, prestige, taste, honor, stigma, and symbolic boundaries organize inclusion and exclusion.', 7),
  ('19ac89d0-6681-4a69-9d87-0323a3f1238e', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '17a812ef-5852-4617-ad1f-1ecc5a334bd7', 'subtopic'::public.curated_course_node_type, 'Status and Prestige', 'Students learn Weber''s insight that honor and social standing stratify people beyond class alone.', 0),
  ('02e36b19-bf72-4890-bc5f-6bb85a998901', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '19ac89d0-6681-4a69-9d87-0323a3f1238e', 'concept'::public.curated_course_node_type, 'Status groups', null, 0),
  ('06637088-cbec-43a4-996a-c747369744f4', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '19ac89d0-6681-4a69-9d87-0323a3f1238e', 'concept'::public.curated_course_node_type, 'Occupational prestige', null, 1),
  ('7eacf7c1-9e5f-4443-b9df-38db71fe390c', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '19ac89d0-6681-4a69-9d87-0323a3f1238e', 'concept'::public.curated_course_node_type, 'Respectability and honor', null, 2),
  ('763f6db0-f261-4688-a16d-165ffc4b4302', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '19ac89d0-6681-4a69-9d87-0323a3f1238e', 'concept'::public.curated_course_node_type, 'Stigma and spoiled identity', null, 3),
  ('3b899e11-b21a-404e-a670-8f5f95d84dda', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '17a812ef-5852-4617-ad1f-1ecc5a334bd7', 'subtopic'::public.curated_course_node_type, 'Culture and Taste', 'The gist is understanding how preferences can become social boundaries.', 1),
  ('1cc4e04f-781a-4ddd-9c0a-c83023d34868', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '3b899e11-b21a-404e-a670-8f5f95d84dda', 'concept'::public.curated_course_node_type, 'Bourdieu and distinction', null, 0);
