  ('ba0f668b-97b6-497e-9e8a-9dab01ece496', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', '582cc336-2b56-4b8f-9686-8f89b537a737', 'concept'::public.curated_course_node_type, 'Recognition, misrecognition, and dignity', null, 3),
  ('062b5448-85b3-4e0a-982a-dee76fc0ed3c', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Power, Elites, Organizations, the State, and Institutional Advantage', 'This unit treats inequality as institutional power. Students learn how elites, organizations, laws, markets, and states create durable advantage.', 8),
