  ('ece4ff4f-783b-4f5e-917d-0fb5483ca37a', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', 'e529af0f-d8a4-4aa7-bd0f-2a2ae6281316', 'concept'::public.curated_course_node_type, 'Economic, political, professional, and cultural elites', null, 0),
