  ('f30d8a6c-cfd7-4d84-9f1a-4b6dd43ed5bc', 'd9e0f1a2-3b4c-4e99-8f89-0a1b2c3d4e99', null, 'topic'::public.curated_course_node_type, 'Race, Gender, Class, Intersectionality, and Structural Inequality', 'Intersectionality prevents one-axis explanations. Students learn how race, gender, class, sexuality, disability, immigration status, and citizenship combine through institutions.', 9),
